//! The site's data is generated by the library, never typed by hand.
//!
//! `site/static/data/` holds the front page's chart (the `cold-snap` report), the table of all
//! reference days, and the test vectors the floor calculator checks itself against in the
//! browser. This test regenerates them and fails if what is committed differs — so a change to
//! the rules or the simulator cannot leave the site telling an old story.
//! `FMS_UPDATE_SITE=1 cargo test --release --test site` rewrites them.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic, clippy::indexing_slicing)]

use fms::model::{Connection, ControlMode, Device, DeviceKind};
use fms::rules::RuleSet;
use fms::sim;
use fms::units::Kw;
use jiff::SignedDuration;
use jiff::civil::date;
use serde_json::{Value, json};
use std::path::PathBuf;

fn vectors() -> Value {
    let rules = RuleSet::bk6_22_300();
    let on = date(2026, 1, 15);
    let kinds = [DeviceKind::HeatPump, DeviceKind::ChargingPoint, DeviceKind::Cooling, DeviceKind::Storage];
    let powers = [3.0, 4.2, 4.3, 7.0, 9.0, 11.0, 12.0, 15.0, 22.0];
    let mut out = Vec::new();
    let mut k = 0usize;
    for mode in [ControlMode::Ems, ControlMode::Direct] {
        for n in 1..=4usize {
            for start in 0..9usize {
                k += 1;
                let devices: Vec<Device> = (0..n)
                    .map(|i| Device {
                        id: format!("d{i}"),
                        kind: kinds[(k + i * 3) % 4],
                        nominal: Kw(powers[(start + i * 4 + k) % powers.len()]),
                        commissioned: date(2025, 1, 1),
                        opted_in: false,
                        exempt: false,
                    })
                    .collect();
                let c = Connection {
                    id: "v".into(),
                    resource: None,
                    node: "N".into(),
                    mode,
                    area: String::new(),
                    postcode: String::new(),
                    devices: devices.clone(),
                    relay_only: false,
                    failsafe: None,
                    failsafe_for: SignedDuration::from_hours(2),
                    fuse: Kw(100.0),
                };
                let floor = rules.floor(&c, on).map(|f| f.total.round_w().0);
                out.push(json!({
                    "mode": if mode == ControlMode::Ems { "ems" } else { "direct" },
                    "devices": devices.iter().map(|d| json!({ "kind": d.kind, "kw": d.nominal.0 })).collect::<Vec<_>>(),
                    "floor": floor,
                }));
            }
        }
    }
    Value::Array(out)
}

fn reports() -> (Value, Value) {
    let runs: Vec<_> = sim::days().iter().map(|d| sim::run(d, 1).unwrap().report).collect();
    let cold = serde_json::to_value(runs.iter().find(|r| r.day == "cold-snap").unwrap()).unwrap();
    let days: Vec<Value> = runs
        .iter()
        .map(|r| {
            let mut v = serde_json::to_value(r).unwrap();
            if let Some(o) = v.as_object_mut() {
                o.remove("series");
                o.remove("story");
            }
            v
        })
        .collect();
    (cold, Value::Array(days))
}

#[test]
fn the_site_data_is_what_the_library_says() {
    let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("site/static/data");
    let (cold, days) = reports();
    let files = [("cold-snap.json", cold), ("days.json", days), ("floor-vectors.json", vectors())];
    let update = std::env::var_os("FMS_UPDATE_SITE").is_some();
    let mut stale = Vec::new();
    for (name, value) in files {
        let path = dir.join(name);
        let fresh = serde_json::to_string_pretty(&value).unwrap() + "\n";
        if update {
            std::fs::create_dir_all(&dir).unwrap();
            std::fs::write(&path, &fresh).unwrap();
        } else if std::fs::read_to_string(&path).ok().as_deref() != Some(fresh.as_str()) {
            stale.push(name);
        }
    }
    assert!(stale.is_empty(), "site data is stale: {stale:?} — run FMS_UPDATE_SITE=1 cargo test --release --test site");
}
